Section CSELS_TAIL.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.
Hypothesis GP : rt_gaps RT.
Hypothesis FKC : rt_fk_contracts RT.
Variables (Σ : rts RT) (PMc : Model -> Prop) (ra gp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word)
          (usp lo : Z) (m : mem) (size dir p1 p2 : Z) (ras : list Z).
Hypothesis CTX : csels_ctx RT Σ PMc ra usp lo m size dir p1 p2 ras.

(* [comment removed for export] *)
Ltac ivls5 LOR W1C W2C :=
  cbn [ivls_client]; split;
  [ intros zz Hzz; left; lazymatch goal with T : (_ + 16 <= 140737488355328)%Z |- _ => clear - Hzz T LOR end; ul
  | split; [intros zz Hzz; right; right; right; left; apply (W1C _ zz); [solve [frames_sub_tac]| clear - Hzz; lia]
  | split; [intros zz Hzz; right; right; right; left; apply (W2C _ zz); [solve [frames_sub_tac]| clear - Hzz; lia]
  | split; [intros zz Hzz; fframe_tac| split; [intros zz Hzz; fframe_tac| exact I]]]]].
Ltac pf5 PFS NFA LOR Hx :=
  let Q1 := fresh "Q" in
  cbn [outside]; destruct Hx as [Hx1 Hx2]; pose proof (PFS _ (conj Hx1 Hx2)) as Q1; destruct (NFA _ (conj Hx1 Hx2)) as [N1 N2];
  cbn [outside] in Hx2; unfold shad, SHB in N1, N2; clear - Q1 Hx2 N1 N2 LOR; repeat split; try exact I; first [lia | Z.div_mod_to_equations; lia].
(* [comment removed for export] *)
(* [comment removed for export] *)
Ltac ss_call2 AF PFS NFA LOR W1C W2C usp SSL SA SB :=
  let W := fresh "WSA" in pose proof (proj2 SA) as W; cbn [cells_size csize Nat.add length Z.of_nat Pos.of_succ_nat Pos.succ] in W;
  once (at_call RT AF ltac:(ivls5 LOR W1C W2C) ltac:(fun Hx => pf5 PFS NFA LOR Hx));
  once (eapply cps_seq;
  [ let SS := fresh "SS" in pose proof SSL as SS; unfold set_shadow_contractF in SS;
    eapply SS with (n := 128); rt_side idtac;
    first [ exact W | solve [apply (wr_at_sub _ _ _ _ _ W); lia] | lazymatch goal with |- ?g => idtac "ss_call LEFT:" g end ]
  | ]);
  once (after_call RT AF);
  once (fold_ag ltac:(fun Hx => let N1 := fresh "N" in let N2 := fresh "N" in pose proof (NFA _ Hx) as [N1 N2]; unfold shad, SHB in N1, N2; split;
                [ apply (aclient_mono _ _ usp _ _ _ _ (proj1 Hx)); [solve [live_sub_tac]| solve [frames_sub_tac]| lia]
                | clear - N1 N2; Z.div_mod_to_equations; lia ]));
  once (lazymatch goal with B : bytes_at asegs ?m2 ?d (repeat ?b (Z.to_nat 128)) |- _ =>
    assert (SB : rw_cells asegs m2 d [CB 128%nat (repeat b 128%nat)])
      by (change (Z.to_nat 128) with 128%nat in B; split;
          [ split; [cbn; split; [reflexivity| exact I]| cbn [cells_bytes cbytes]; rewrite app_nil_r; exact B]
          | cbn [cells_size csize Nat.add Z.of_nat Pos.of_succ_nat Pos.succ];
            first [exact W | apply (wr_at_sub _ _ _ _ _ W); lia] ]);
    clear B
  end);
  clear W; try clear SA;
  once (refresh RT AF); unfold shad, SHB in *; unfold STACK_WIN, USTACK_TOP, RT_STACK, SEGTOP_A in *;
  repeat match goal with H : rt_sp0 RT _ = _ |- _ => rewrite H in * end.
Ltac hsum mm := repeat match goal with H : ?T |- _ => lazymatch T with context [mm] => first [ lazymatch T with rw_cells _ _ ?A _ => idtac H ": cells at" A | accok _ _ _ ?a _ => idtac H ": accok" a | acc _ _ ?a ?n => idtac H ": acc" a n | wr_at _ _ ?a ?n => idtac H ": wr_at" a n end | idtac H ]; fail end end.
Ltac hs := lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) => idtac "cur mem" mm; hsum mm | |- cps _ (ASTA _ _ _ (eq (MS _ _ _ _ _ ?mm _))) _ =>  idtac "cur mem" mm; hsum mm end.
Ltac show_pc := lazymatch goal with
  | |- cps _ (ASTA _ _ _ (eq (MS _ _ ?pc _ _ _ _))) _ => idtac "CPS-MS pc=" pc
  | |- cps _ (ASTA _ _ _ (eq ?st)) _ => idtac "CPS other"
  | |- evt _ _ (MS _ _ ?pc _ _ _ _) => idtac "EVT pc=" pc
  | |- ?g => idtac "OTHER" end.

(* [comment removed for export] *)
Ltac brS SHAPE := lazymatch goal with
  | |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
      first [ replace c with true by (clear - SHAPE; destruct SHAPE as [(-> & ->)|(-> & ->)]; vm_compute; reflexivity); cbv iota
            | replace c with false by (clear - SHAPE; destruct SHAPE as [(-> & ->)|(-> & ->)]; vm_compute; reflexivity); cbv iota ]
  | |- _ => idtac end.


(* [comment removed for export] *)
Ltac ss_call3 AF PFS NFA LOR W1C W2C usp SSL W :=
  once (at_call RT AF ltac:(ivls5 LOR W1C W2C) ltac:(fun Hx => pf5 PFS NFA LOR Hx));
  once (eapply cps_seq;
  [ let SS := fresh "SS" in pose proof SSL as SS; unfold set_shadow_contractF in SS;
    eapply SS with (n := 128); rt_side idtac;
    first [ exact W | solve [apply (wr_at_sub _ _ _ _ _ W); lia] | lazymatch goal with |- ?g => idtac "ss_call LEFT:" g end ]
  | ]);
  once (after_call RT AF);
  once (fold_ag ltac:(fun Hx => let N1 := fresh "N" in let N2 := fresh "N" in pose proof (NFA _ Hx) as [N1 N2]; unfold shad, SHB in N1, N2; split;
                [ apply (aclient_mono _ _ usp _ _ _ _ (proj1 Hx)); [solve [live_sub_tac]| solve [frames_sub_tac]| lia]
                | clear - N1 N2; Z.div_mod_to_equations; lia ]));
  repeat match goal with B : bytes_at asegs _ _ (repeat _ (Z.to_nat 128)) |- _ => clear B end;
  once (refresh RT AF); unfold shad, SHB in *; unfold STACK_WIN, USTACK_TOP, RT_STACK, SEGTOP_A in *;
  repeat match goal with H : rt_sp0 RT _ = _ |- _ => rewrite H in * end.

Ltac preg k := lazymatch goal with |- evt _ _ (MS ?R _ _ _ _ _ _) =>
  let p := eval vm_compute in (bv_key (Z_to_bv 5 k)) in
  let v := eval cbv beta iota delta [tget mkR] in (tget p R) in idtac "reg" k "=" v end.
(* [comment removed for export] *)
Ltac lit_reg k := lazymatch goal with |- evt _ _ (MS ?R _ _ _ _ _ _) =>
  let p := eval vm_compute in (bv_key (Z_to_bv 5 k)) in
  let v := eval cbv beta iota delta [tget mkR] in (tget p R) in
  lazymatch v with
  | Some (Z_to_bv 64 ?z) =>
      first [ is_Zlit z
            | let c := eval vm_compute in z in replace (Z_to_bv 64 z) with (Z_to_bv 64 c) by (apply f_equal; vm_compute; reflexivity) ]
  | Some ?t => fp_lit t end end.
(* [comment removed for export] *)
Ltac lit_fregs := repeat lazymatch goal with |- evt _ _ (MS _ ?FF _ _ _ _ _) =>
  lazymatch FF with context [fadd_d ?md ?x ?y] => fp_lit (fadd_d md x y) | context [fsqrt_d ?md ?x] => fp_lit (fsqrt_d md x)
                   | context [fcvt_d_wu ?md ?x] => fp_lit (fcvt_d_wu md x) end end.
(* [comment removed for export] *)
Ltac loop1 := repeat (lazymatch goal with |- evt _ _ (MS _ _ (Z_to_bv 64 1411312) _ _ _ _) => lit_reg 16%Z; awalk1; awalk [0x1588f0; 0x158a2c] end).
(* [comment removed for export] *)
Ltac fs_to F Ft :=
  first [ apply fs_agree_refl
        | match goal with H : fs_agree ?Fm Ft |- _ => apply (fs_agree_trans F Fm Ft); [fs_to F Fm | exact H] end
        | lazymatch Ft with bvmap_set ?k ?v ?F' => apply (fs_agree_set_other F F' k v); [reflexivity | fs_to F F'] end ].


